function euler_char(n, h):
  total <- 0
  for p in 0..n:
    for q in 0..n:
      total <- total + (-1)^(p+q) * h(p,q)
  return total

function mirror(n, h):
  return (p,q) |-> h(n-p, q)   # truncated subtraction

